<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/lib/HostingSecrets.php';
$token=rx_env('REDFOX_RESELLER_API_TOKEN');$url=$argv[1]??'https://example.com/api/reseller.php';if(!$token)exit("Set REDFOX_RESELLER_API_TOKEN\n");$payload=['action'=>'message','user_id'=>'123456789','message'=>'پیام آزمایشی'];$body=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$ts=time();$nonce=bin2hex(random_bytes(16));$idem=bin2hex(random_bytes(16));$path=(string)parse_url($url,PHP_URL_PATH);$canonical=$ts."\n".$nonce."\nPOST\n".$path."\n".hash('sha256',$body);$sig=hash_hmac('sha256',$canonical,$token);$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Content-Type: application/json','X-RF-Timestamp: '.$ts,'X-RF-Nonce: '.$nonce,'X-RF-Signature: '.$sig,'Idempotency-Key: '.$idem]]);$resp=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);echo"HTTP $code\n$resp\n";
